{
  "name": "opencode-vibe-webhook",
  "version": "1.0.3",
  "description": "OpenCode plugin for VibeControls notifications - companion to @burdenoff/vibe-plugin-notify",
  "author": {
    "name": "Vignesh T.V",
    "email": "vignesh@burdenoff.com",
    "url": "https://github.com/tvvignesh"
  },
  "license": "MIT",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "vibecontrols",
    "vibe-plugin-notify",
    "webhook",
    "notification",
    "slack",
    "discord",
    "task-completion"
  ],
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "bun build src/index.ts --outdir dist --target node --format esm --external @opencode-ai/plugin && tsc --emitDeclarationOnly --declaration --outDir dist",
    "dev": "bun run build --watch",
    "typecheck": "tsc --noEmit",
    "lint": "eslint ./src",
    "format": "prettier --write .",
    "format:check": "prettier --check .",
    "clean": "rm -rf dist",
    "prepublishOnly": "bun run build",
    "sanity": "bun run format:check && bun run lint && bun run typecheck && bun run build"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.2.15"
  },
  "devDependencies": {
    "@eslint/js": "^10.0.0",
    "@types/bun": "^1.2.0",
    "@types/node": "^22.0.0",
    "eslint": "^9.0.0",
    "globals": "^17.0.0",
    "prettier": "^3.0.0",
    "typescript": "^5.8.0",
    "typescript-eslint": "^8.0.0"
  },
  "engines": {
    "node": ">=18.0.0",
    "bun": ">=1.0.0"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/algoshred/opencode-vibe-webhook.git"
  },
  "bugs": {
    "url": "https://github.com/algoshred/opencode-vibe-webhook/issues"
  },
  "homepage": "https://github.com/algoshred/opencode-vibe-webhook#readme"
}
